const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';

function getDatabaseUrl() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Environment file '${ENV_FILE}' not found.`);
      process.exit(1);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const match = line.match(/^DATABASE_URL=(.+)$/);
      if (match) {
        return match[1].trim();
      }
    }

    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  } catch (error) {
    console.error('Error reading environment file:', error);
    process.exit(1);
  }
}

function logConnection(databaseUrl) {
  // Mask the password in the connection string for security
  const maskedUrl = databaseUrl.replace(/:([^:@]+)@/, ':****@');
  console.log(`Connected successfully to: ${maskedUrl}`);
}

async function runMigrations() {
  try {
    // Read and resolve connection string
    const databaseUrl = getDatabaseUrl();
    logConnection(databaseUrl);
    console.log('');

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    // Log each filename that would be applied
    console.log('Migration files to be applied:');
    console.log('----------------------------');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
    console.log('----------------------------');
    console.log(`Total: ${sqlFiles.length} migration(s)`);

  } catch (error) {
    console.error('Error running migrations:', error);
    process.exit(1);
  }
}

