const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';

function loadEnvFile(filePath) {
    try {
        if (!fs.existsSync(filePath)) {
            console.log(`Environment file '${filePath}' does not exist.`);
            return null;
        }

        const envContent = fs.readFileSync(filePath, 'utf-8');
        const envVars = {};

        envContent.split('\n').forEach(line => {
            const trimmedLine = line.trim();
            if (trimmedLine && !trimmedLine.startsWith('#')) {
                const [key, ...valueParts] = trimmedLine.split('=');
                if (key && valueParts.length > 0) {
                    envVars[key.trim()] = valueParts.join('=').trim();
                }
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

function runMigrations() {
    // Load environment variables from .env.test
    const envVars = loadEnvFile(ENV_FILE);

    if (!envVars) {
        console.log('Failed to load environment variables. Exiting.');
        return;
    }

    const databaseUrl = envVars.DATABASE_URL;

    if (!databaseUrl) {
        console.log('DATABASE_URL not found in environment variables. Exiting.');
        return;
    }

    console.log('Connected successfully to database');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            return;
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        // Log each filename that would be applied
        console.log('Applying migrations in order:');
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

    } catch (error) {
        console.error('Error reading migrations:', error.message);
    }
}

runMigrations();

