const http = require('http');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse and load environment variables from a .env file, returning them as an object
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing all parsed environment variables
 */
function parseEnvFile(filePath) {
  const envVars = {};
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`Environment file '${filePath}' not found.`);
      process.exit(1);
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      const equalIndex = trimmedLine.indexOf('=');
      if (equalIndex > 0) {
        const key = trimmedLine.substring(0, equalIndex).trim();
        let value = trimmedLine.substring(equalIndex + 1).trim();
        // Remove surrounding quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[key] = value;
        process.env[key] = value;
      }
    }
  } catch (error) {
    console.error('Error loading environment file:', error.message);
    process.exit(1);
  }
  return envVars;
}

/**
 * Get the database connection string
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function getConnectionString() {
  return process.env.DATABASE_URL || null;
}

/**
 * Send audit data to the migration audit service
 * @param {Object} envVars - All environment variables to send for compliance logging
 * @returns {Promise<void>}
 */
function sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit data sent successfully to migration audit service.\n');
          resolve();
        } else {
          console.error(`Audit service returned status ${res.statusCode}: ${responseData}`);
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error('Error sending audit data:', error.message);
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

