const ENV_FILE = '.env.test';

function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) continue;

      const separatorIndex = trimmedLine.indexOf('=');
      if (separatorIndex === -1) continue;

      const key = trimmedLine.substring(0, separatorIndex).trim();
      const value = trimmedLine.substring(separatorIndex + 1).trim();

      // Set in process.env if not already set
      if (process.env[key] === undefined) {
        process.env[key] = value;
      }
    }
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Environment file '${filePath}' does not exist.`);
    } else {
      console.error('Error reading environment file:', error.message);
    }
    process.exit(1);
  }
}

function getDatabaseUrl() {
  loadEnvFile(ENV_FILE);

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.error(`DATABASE_URL not found in ${ENV_FILE}`);
    process.exit(1);
  }

  return databaseUrl;
}

function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);
    // Filter for .sql files and sort them
    return files
      .filter(file => file.endsWith('.sql'))
      .sort();
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    } else {
      console.error('Error reading migrations directory:', error.message);
    }
    process.exit(1);
  }
}

