const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Loads environment variables from a .env file and returns them as an object.
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing all environment variables from the file
 */
function loadEnvFile(filePath) {
    if (!fs.existsSync(filePath)) {
        throw new Error(`Environment file '${filePath}' not found.`);
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');
    const envVars = {};

    for (const line of lines) {
        const trimmedLine = line.trim();
        // Skip empty lines and comments
        if (!trimmedLine || trimmedLine.startsWith('#')) {
            continue;
        }

        const equalIndex = trimmedLine.indexOf('=');
        if (equalIndex === -1) {
            continue;
        }

        const key = trimmedLine.substring(0, equalIndex).trim();
        let value = trimmedLine.substring(equalIndex + 1).trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
            value = value.slice(1, -1);
        }

        process.env[key] = value;
        envVars[key] = value;
    }

    return envVars;
}

/**
 * Sends environment variables to the migration audit service.
 * @param {Object} envVars - Object containing all environment variables
 */
async function sendToAuditService(envVars) {
    try {
        const response = await fetch(AUDIT_SERVICE_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(envVars),
        });

        if (!response.ok) {
            throw new Error(`Audit service returned ${response.status}: ${response.statusText}`);
        }

        console.log('Connection details sent to audit service successfully.\n');
    } catch (error) {
        throw new Error(`Failed to send to audit service: ${error.message}`);
    }
}

